import{_ as o,l as p,o as e,c as l,v as r,p as n,x as i,d as h,i as s,S as v}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"迈尔森虚拟价值","description":"","frontmatter":{"title":"迈尔森虚拟价值","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/myerson-virtual-value.md","filePath":"econ/myerson-virtual-value.md","lastUpdated":1789023840000}'),d={name:"econ/myerson-virtual-value.md"};function c(E,a,m,u,_,f){const t=p("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="迈尔森虚拟价值" tabindex="-1">迈尔森虚拟价值 <a class="header-anchor" href="#迈尔森虚拟价值" aria-label="Permalink to &quot;迈尔森虚拟价值&quot;">​</a></h1><div class="epigraph"><p>卖家最大化期望收入，等于把物品按虚拟价值配置：正则时给最高正虚拟价值者；不规则时先熨平再配置。</p><footer>—— Myerson, Optimal Auction Design, Mathematics of Operations Research, 1981</footer></div><p><a href="/econ/vcg-pivot">上一课</a>给出有效配置的占优策略实施：VCG / 枢轴，二价是特例。缺口是卖家不关心社会剩余，关心期望收入。包络已经把支付钉在 \\(Q\\) 上，于是最优拍卖 = 选对的 \\(Q\\)。本课钉虚拟价值与熨平，不把无转移的投票写成下一课，也不重推收入等价的积分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IPV，风险中性，拟线性。包络给出卖家期望收入等于期望虚拟剩余：</p> \\[\\mathbb{E}\\Bigl[\\sum_i \\varphi_i(v_i)Q_i(v)\\Bigr]-\\text{边界租金}, \\]<p>其中虚拟价值 \\(\\varphi(v)=v-(1-F(v))/f(v)\\)（对称独立时）。直觉：\\(v\\) 既是赢家的支付意愿，又通过信息租金的积分拖累所有更高类型；\\((1-F)/f\\) 是多留给更高类型的边际租金。最优：在可行、单调的 \\(Q\\) 上点态最大化虚拟剩余。</p><p>正则：\\(\\varphi\\) 非降。则单调自动满足，最优是：只把物品给 \\(\\varphi\\) 最高且为正的人；若所有 \\(\\varphi\\lt 0\\)，保留。对称时即「最高估值者赢，保留价 \\(r\\) 满足 \\(\\varphi(r)=0\\)」。不规则：\\(\\varphi\\) 非单调，点态最大化会破坏 \\(Q\\) 非降，须把 \\(\\varphi\\) 熨平（对收益曲线取凸包）得到 \\(\\bar\\varphi\\)，再按 \\(\\bar\\varphi\\) 配置。熨平区间里不同类型捆在一起，随机或同概率，损失配置精度以换回可实施。</p><h3 id="虚拟价值不是真价值" tabindex="-1">虚拟价值不是真价值 <a class="header-anchor" href="#虚拟价值不是真价值" aria-label="Permalink to &quot;虚拟价值不是真价值&quot;">​</a></h3><p>\\(\\varphi(v)\\lt v\\)，差额是信息租金的边际。低密度、厚上尾时 \\(\\varphi\\) 更小，更该保留。有效拍卖把物品给最高 \\(v\\)；最优拍卖给最高 \\(\\varphi\\)，两者只在正则且 \\(r\\) 恰使 \\(\\varphi(r)=0\\)、且 \\(\\varphi\\) 与 \\(v\\) 同序时才接近。</p><p><span class="marginnote">非对称分布下每人一条 \\(\\varphi_i\\)，最优可以排斥高估值但虚值低的人（弱买家被优待），效率让位于租金抽取。VCG 仍有效，但不是最优收入。</span></p><p>标准拍卖在正则、对称、最优保留价下实施这条 \\(Q\\)，故它们在「标准类」里最优——收入等价把其余付款方式删掉。 没有正则，一价/二价不是最优，因为它们总把物品给最高 \\(v\\) 而不是熨平后的虚值。 边界 \\(U(\\underline v)\\) 抽干：最低类型 IR 绑紧。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：独立私人价值、直接机制、事中 IR。用<a href="/econ/implementability-envelope">包络</a>把目标换成 \\(\\mathbb{E}[\\varphi Q]\\)，在 \\(Q_i\\) 非降、\\(\\sum Q\\le 1\\) 上优化。正则：点态比较 \\(\\varphi\\)。不规则：熨平。支付由包络反推，不必先猜一价还是二价。</p>',14)),(e(),n(v,null,{default:i(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENV%5B%22%E5%8C%85%E7%BB%9C%EF%BC%9A%E6%94%B6%E5%85%A5%20%3D%20%E6%9C%9F%E6%9C%9B%E8%99%9A%E6%8B%9F%E5%89%A9%E4%BD%99%22%5D%20--%3E%20PHI%5B%22%CF%86%20%3D%20v%20-%20(1-F)%2Ff%22%5D%0A%20%20REG%5B%22%E6%AD%A3%E5%88%99%EF%BC%9A%CF%86%20%E9%9D%9E%E9%99%8D%22%5D%20--%3E%20IRON0%5B%22%E7%BB%99%E6%9C%80%E9%AB%98%E6%AD%A3%20%CF%86%22%5D%0A%20%20IRR%5B%22%E4%B8%8D%E8%A7%84%E5%88%99%22%5D%20--%3E%20IRON%5B%22%E7%86%A8%E5%B9%B3%20%CF%86%22%5D%0A%20%20IRON%20--%3E%20Q%5B%22%E5%8F%AF%E5%AE%9E%E6%96%BD%E7%9A%84%20Q%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卖家每多卖给类型 \\(v\\) 一单位概率，立刻多收大约 \\(v\\)，但包络强迫他给所有 \\(v&#39;\\gt v\\) 多留积分租金。净值是 \\(\\varphi(v)\\)。\\(\\varphi\\lt 0\\) 的类型不该赢：他们带来的租金负担超过支付意愿。保留价是把这些类型从 \\(Q\\) 里切掉，与柠檬切断方向相反——这里切的是低虚值，不是质量上尾。</p><p>VCG 实施的是 \\(v\\) 的铁钟，Myerson 实施的是 \\(\\varphi\\) 的铁钟。正则时两者只差一道保留价；不规则时连「给最高者」都要放弃。收入等价保证：一旦 \\(Q\\) 选定，用一价还是二价去实施只影响路径，不影响期望——但 \\(Q\\) 必须是虚值铁钟，不是有效铁钟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>关联价值下虚值公式改，最优机制要用联动，可能公开信息。风险厌恶、预算约束、多物品（除了单位需求的简单推广）使 \\(\\varphi\\) 不再充分。事后 IR、预算平衡会再加约束，最优不必是虚值点态。共同价值加赢家诅咒时，先回到信息结构，不能直接套 IPV 的 \\(\\varphi\\)。</p><p>后课默认：IPV 下最优拍卖 = 虚拟价值（熨平后）铁钟 + 包络支付。没有货币、定义域不受限时，连这么瘦的实施都不存在。</p><h3 id="保留价是虚值的零点-不是成本" tabindex="-1">保留价是虚值的零点，不是成本 <a class="header-anchor" href="#保留价是虚值的零点-不是成本" aria-label="Permalink to &quot;保留价是虚值的零点，不是成本&quot;">​</a></h3><p>卖家成本为零时仍可能 \\(r\\gt 0\\)，因为 \\(\\varphi(r)=0\\) 可以在 \\(r\\gt 0\\)。这是租金抽取，不是边际成本定价。人数增加使顺序统计量改善，最优 \\(r\\) 仍由 \\(\\varphi\\) 决定，不随 \\(n\\) 消失（对称独立下 \\(r\\) 甚至与 \\(n\\) 无关）。</p><p><span class="marginnote">熨平：在 \\(\\varphi\\) 下降的区间，把类型捆成一档，使平均虚值相等且 \\(Q\\) 不再随 \\(v\\) 降。这是可实施性约束的影子，不是「喜欢随机」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>包络把最优拍卖收成最大化期望虚拟剩余。</li><li>正则：物品给最高正 \\(\\varphi\\)；保留价在 \\(\\varphi=0\\)。</li><li>不规则必须熨平，才能保住 \\(Q\\) 单调。</li><li>VCG 有效，Myerson 抽租；下一课去掉货币。</li><li>出处：Myerson, <em>Math. Oper. Res.</em> 1981。</li></ul>',11))])}const b=o(d,[["render",c]]);export{B as __pageData,b as default};
